import test from 'node:test';
import assert from 'node:assert/strict';
import {clock,exercise} from 'file:///C:/Users/gwara/furvise-intelligence-v1/scripts/audits/helpers/lifetime-harness.mjs';
import {decisive,care} from 'file:///C:/Users/gwara/furvise-intelligence-v1/scripts/audits/fixtures/ask-lifetime-history.mjs';
import {stressProposal} from 'file:///C:/Users/gwara/furvise-intelligence-v1/scripts/audits/helpers/current-stress-harness.mjs';
for (const hints of [[],['correct','retract','supersed']]) test('typed July domain does not discover later unlinked prose; hints='+hints.length,async t=>{
 clock(t);
 const proposal=stressProposal({authority:'effective_fact',petNames:['Milo'],terms:['vomit','threw up'],from:'2014-07-01',to:'2014-08-01'});
 proposal.readTicket.searchHints=hints;
 const run=await exercise('Did Milo vomit in July 2014?',{history:true,interpretationProposal:proposal,expectedProviderCalls:0,expectedReviewCalls:0});
 assert.equal(run.interpretationRequests.length,1);
 assert.equal(run.requests.length,0);
 assert.equal(run.reviewRequests.length,0);
 const discoveries=run.queries.filter(q=>q.table==='read_ask_history_candidates'&&q.args?.p_terms?.includes('correct'));
 assert.equal(discoveries.length,0);
 assert.ok(!run.context.askHistory.originals.some(r=>r.id==='milo-correction'));
 console.log('BOUNDARY_EVIDENCE',JSON.stringify({hints,request:run.context.askInterpretation.request.readTicket,discoveryQueries:discoveries.length,originalIds:run.context.askHistory.originals.map(r=>r.id),coverage:run.context.askHistory.coverage,model:run.result.reasoning.model,outcome:run.result.answerValidation.assessment.outcome,providerCalls:0}));
});

test('unrelated-year unlinked prose also blocks the July effective result',async t=>{
 clock(t);
 const rows=decisive.filter(r=>!r.id.includes('correction'));
 rows.push(care('other-year','milo','2026-08-20','general','Correction to the 2015 vomiting report.'));
 const proposal=stressProposal({authority:'effective_fact',petNames:['Milo'],terms:['vomit','threw up'],from:'2014-07-01',to:'2014-08-01'});
 const run=await exercise('Did Milo vomit in July 2014?',{rows,history:true,interpretationProposal:proposal,expectedProviderCalls:0,expectedReviewCalls:0});
 assert.equal(run.result.reasoning.model,'server-history-unavailable');
 assert.ok(run.context.askHistory.coverage.ticketCoverage.sourceLineage.some(r=>r.eventId==='other-year'));
 console.log('UNRELATED_YEAR_EVIDENCE',JSON.stringify({sourceLineage:run.context.askHistory.coverage.ticketCoverage.sourceLineage,model:run.result.reasoning.model,outcome:run.result.answerValidation.assessment.outcome}));
});
